		private PreparedStatement TrabajoStmt;
		
		private void initTrabajoStmt() 
		throws SQLException{
			TrabajoStmt = ctsqlConnection.prepareStatement(
					"SELECT *"
					+ " FROM trabajo"
					+ " WHERE" 
					+ " cdg = ?  " 				); 
		}
		
		private void closeTrabajoStmt() 
		throws SQLException{
			TrabajoStmt.close();
		}


		public void visitTrabajo(CtsqlDBVisitor ctsqlDBVisitor) throws SQLException{
			ResultSet 			rs 	= null;
			boolean				resume 	= true;
	
			try {
				
				this.TrabajoStmt.setInt(1, this.getCdg() ); 
				rs = this.TrabajoStmt.executeQuery();
				Trabajo trabajo = new Trabajo(rs); 
				while ( resume && rs.next() ) {
					resume = ctsqlDBVisitor.visitTrabajo(trabajo, this);
				}
			}
			finally {
				if ( rs != null )
					rs.close();
			}
		}
		
