		private PreparedStatement HttbonificacionStmt;
		
		private void initHttbonificacionStmt() 
		throws SQLException{
			HttbonificacionStmt = ctsqlConnection.prepareStatement(
					"SELECT *"
					+ " FROM httbonificacion"
					+ " WHERE" 
					+ " cdg = ?  " 				); 
		}
		
		private void closeHttbonificacionStmt() 
		throws SQLException{
			HttbonificacionStmt.close();
		}


		public void visitHttbonificacion(CtsqlDBVisitor ctsqlDBVisitor) throws SQLException{
			ResultSet 			rs 	= null;
			boolean				resume 	= true;
	
			try {
				
				this.HttbonificacionStmt.setInt(1, this.getCdg() ); 
				rs = this.HttbonificacionStmt.executeQuery();
				Httbonificacion httbonificacion = new Httbonificacion(rs); 
				while ( resume && rs.next() ) {
					resume = ctsqlDBVisitor.visitHttbonificacion(httbonificacion, this);
				}
			}
			finally {
				if ( rs != null )
					rs.close();
			}
		}
		
