	/**
	 * Automat
	 * 
	 */
	public class Automat {
		
		private ResultSet rs;
		
		private String suffix;
		
		private Automat (ResultSet rs) 
		throws SQLException {
			this(rs, "");
		}
		
		private Automat (ResultSet rs, String suffix) 
		throws SQLException {
			this.rs =rs;
			this.suffix = suffix;
			initLinautomStmt();
		}
		
		@Override
		protected void finalize() throws Throwable {
			closeLinautomStmt();
			super.finalize();
		}
		

		/**
		 * Codigo de Fichero Automatico
		 * @return the column 'cdg' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public Integer getCdg()
		throws SQLException {
			return rs.getInt("cdg"+suffix );
		}
		/**
		 * Descripcion de Fichero Automatico
		 * @return the column 'descripcion' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public String getDescripcion()
		throws SQLException {
			return rs.getString("descripcion"+suffix);
		}
		/**
		 * Tipo (Empresas/Trabajadores)
		 * @return the column 'tipo' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public String getTipo()
		throws SQLException {
			return rs.getString("tipo"+suffix);
		}


		
		private PreparedStatement LinautomStmt;
		
		private void initLinautomStmt() 
		throws SQLException{
			LinautomStmt = ctsqlConnection.prepareStatement(
					"SELECT *"
					+ " FROM linautom"
					+ " WHERE" 
					+ " cdg = ?  " 				); 
		}
		
		private void closeLinautomStmt() 
		throws SQLException{
			LinautomStmt.close();
		}


		public void visitLinautom(CtsqlDBVisitor ctsqlDBVisitor) throws SQLException{
			ResultSet 			rs 	= null;
			boolean				resume 	= true;
	
			try {
				
				this.LinautomStmt.setInt(1, this.getCdg() ); 
				rs = this.LinautomStmt.executeQuery();
				Linautom linautom = new Linautom(rs); 
				while ( resume && rs.next() ) {
					resume = ctsqlDBVisitor.visitLinautom(linautom, this);
				}
			}
			finally {
				if ( rs != null )
					rs.close();
			}
		}

		
	}
	
	
