	/**
	 * Ocupacion
	 * 
	 */
	public class Ocupacion {
		
		private ResultSet rs;
		
		private String suffix;
		
		private Ocupacion (ResultSet rs) 
		throws SQLException {
			this(rs, "");
		}
		
		private Ocupacion (ResultSet rs, String suffix) 
		throws SQLException {
			this.rs =rs;
			this.suffix = suffix;
			initLinocupacionStmt();
		}
		
		@Override
		protected void finalize() throws Throwable {
			closeLinocupacionStmt();
			super.finalize();
		}
		

		/**
		 * Código
		 * @return the column 'cdg' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public String getCdg()
		throws SQLException {
			return rs.getString("cdg"+suffix);
		}
		/**
		 * Descripcion
		 * @return the column 'descripcion' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public String getDescripcion()
		throws SQLException {
			return rs.getString("descripcion"+suffix);
		}
		/**
		 * Exclusivo a CNAE
		 * @return the column 'exclusivo' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public String getExclusivo()
		throws SQLException {
			return rs.getString("exclusivo"+suffix);
		}


		
		private PreparedStatement LinocupacionStmt;
		
		private void initLinocupacionStmt() 
		throws SQLException{
			LinocupacionStmt = ctsqlConnection.prepareStatement(
					"SELECT *"
					+ " FROM linocupacion"
					+ " WHERE" 
					+ " cdg = ?  " 				); 
		}
		
		private void closeLinocupacionStmt() 
		throws SQLException{
			LinocupacionStmt.close();
		}


		public void visitLinocupacion(CtsqlDBVisitor ctsqlDBVisitor) throws SQLException{
			ResultSet 			rs 	= null;
			boolean				resume 	= true;
	
			try {
				
				this.LinocupacionStmt.setString(1, this.getCdg() ); 
				rs = this.LinocupacionStmt.executeQuery();
				Linocupacion linocupacion = new Linocupacion(rs); 
				while ( resume && rs.next() ) {
					resume = ctsqlDBVisitor.visitLinocupacion(linocupacion, this);
				}
			}
			finally {
				if ( rs != null )
					rs.close();
			}
		}

		
	}
	
	
