		private PreparedStatement NomdtoStmt;
		
		private void initNomdtoStmt() 
		throws SQLException{
			NomdtoStmt = ctsqlConnection.prepareStatement(
					"SELECT *"
					+ " FROM nomdto"
					+ " WHERE" 
					+ " cdg = ?  " 				); 
		}
		
		private void closeNomdtoStmt() 
		throws SQLException{
			NomdtoStmt.close();
		}


		public void visitNomdto(CtsqlDBVisitor ctsqlDBVisitor) throws SQLException{
			ResultSet 			rs 	= null;
			boolean				resume 	= true;
	
			try {
				
				this.NomdtoStmt.setInt(1, this.getCdg() ); 
				rs = this.NomdtoStmt.executeQuery();
				Nomdto nomdto = new Nomdto(rs); 
				while ( resume && rs.next() ) {
					resume = ctsqlDBVisitor.visitNomdto(nomdto, this);
				}
			}
			finally {
				if ( rs != null )
					rs.close();
			}
		}
		
