		private PreparedStatement Lintc2epiStmt;
		
		private void initLintc2epiStmt() 
		throws SQLException{
			Lintc2epiStmt = ctsqlConnection.prepareStatement(
					"SELECT *"
					+ " FROM lintc2epi"
					+ " WHERE" 
					+ " cdg = ?  " 				); 
		}
		
		private void closeLintc2epiStmt() 
		throws SQLException{
			Lintc2epiStmt.close();
		}


		public void visitLintc2epi(CtsqlDBVisitor ctsqlDBVisitor) throws SQLException{
			ResultSet 			rs 	= null;
			boolean				resume 	= true;
	
			try {
				
				this.Lintc2epiStmt.setInt(1, this.getCdg() ); 
				rs = this.Lintc2epiStmt.executeQuery();
				Lintc2epi lintc2epi = new Lintc2epi(rs); 
				while ( resume && rs.next() ) {
					resume = ctsqlDBVisitor.visitLintc2epi(lintc2epi, this);
				}
			}
			finally {
				if ( rs != null )
					rs.close();
			}
		}
		
