	/**
	 * Tipaut
	 * 
	 */
	public class Tipaut {
		
		private ResultSet rs;
		
		private String suffix;
		
		private Tipaut (ResultSet rs) 
		throws SQLException {
			this(rs, "");
		}
		
		private Tipaut (ResultSet rs, String suffix) 
		throws SQLException {
			this.rs =rs;
			this.suffix = suffix;
			initTrabajoStmt();
		}
		
		@Override
		protected void finalize() throws Throwable {
			closeTrabajoStmt();
			super.finalize();
		}
		

		/**
		 * Codigo de Tipo de Autorización
		 * @return the column 'cdg' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public String getCdg()
		throws SQLException {
			return rs.getString("cdg"+suffix);
		}
		/**
		 * Descripcion de Tipo de Autorización
		 * @return the column 'descripcion' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public String getDescripcion()
		throws SQLException {
			return rs.getString("descripcion"+suffix);
		}


		
		private PreparedStatement TrabajoStmt;
		
		private void initTrabajoStmt() 
		throws SQLException{
			TrabajoStmt = ctsqlConnection.prepareStatement(
					"SELECT *"
					+ " FROM trabajo"
					+ " WHERE" 
					+ " autorizacion = ?  " 				); 
		}
		
		private void closeTrabajoStmt() 
		throws SQLException{
			TrabajoStmt.close();
		}


		public void visitTrabajo(CtsqlDBVisitor ctsqlDBVisitor) throws SQLException{
			ResultSet 			rs 	= null;
			boolean				resume 	= true;
	
			try {
				
				this.TrabajoStmt.setString(1, this.getCdg() ); 
				rs = this.TrabajoStmt.executeQuery();
				Trabajo trabajo = new Trabajo(rs); 
				while ( resume && rs.next() ) {
					resume = ctsqlDBVisitor.visitTrabajo(trabajo, this);
				}
			}
			finally {
				if ( rs != null )
					rs.close();
			}
		}

		
	}
	
	
