	/**
	 * Prestaciones
	 * 
	 */
	public class Prestaciones {
		
		private ResultSet rs;
		
		private String suffix;
		
		private Prestaciones (ResultSet rs) 
		throws SQLException {
			this(rs, "");
		}
		
		private Prestaciones (ResultSet rs, String suffix) 
		throws SQLException {
			this.rs =rs;
			this.suffix = suffix;
			initLinprestacionStmt();
		}
		
		@Override
		protected void finalize() throws Throwable {
			closeLinprestacionStmt();
			super.finalize();
		}
		

		/**
		 * Código de Centro de Trabajo
		 * @return the column 'cdg' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public Integer getCdg()
		throws SQLException {
			return rs.getInt("cdg"+suffix );
		}

		
		private Domicilio rel_pre_dom; 
		
		/**
		 * @throws SQLException
		 */
		public Domicilio getRel_pre_dom()
		throws SQLException {
			if ( this.rel_pre_dom == null )
				this.rel_pre_dom = new Domicilio(rs, "1");
			return this.rel_pre_dom;
		}

		
		private PreparedStatement LinprestacionStmt;
		
		private void initLinprestacionStmt() 
		throws SQLException{
			LinprestacionStmt = ctsqlConnection.prepareStatement(
					"SELECT *"
					+ " FROM linprestacion"
					+ " WHERE" 
					+ " cdg = ?  " 				); 
		}
		
		private void closeLinprestacionStmt() 
		throws SQLException{
			LinprestacionStmt.close();
		}


		public void visitLinprestacion(CtsqlDBVisitor ctsqlDBVisitor) throws SQLException{
			ResultSet 			rs 	= null;
			boolean				resume 	= true;
	
			try {
				
				this.LinprestacionStmt.setInt(1, this.getCdg() ); 
				rs = this.LinprestacionStmt.executeQuery();
				Linprestacion linprestacion = new Linprestacion(rs); 
				while ( resume && rs.next() ) {
					resume = ctsqlDBVisitor.visitLinprestacion(linprestacion, this);
				}
			}
			finally {
				if ( rs != null )
					rs.close();
			}
		}

		
	}
	
	
