	/**
	 * Action
	 * 
	 */
	public class Action {
		
		private ResultSet rs;
		
		private String suffix;
		
		private Action (ResultSet rs) 
		throws SQLException {
			this(rs, "");
		}
		
		private Action (ResultSet rs, String suffix) 
		throws SQLException {
			this.rs =rs;
			this.suffix = suffix;
			initAction_deniedStmt();
		}
		
		@Override
		protected void finalize() throws Throwable {
			closeAction_deniedStmt();
			super.finalize();
		}
		

		/**
		 * Identificador unico
		 * @return the column 'id' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public Integer getId()
		throws SQLException {
			return rs.getInt("id"+suffix );
		}
		/**
		 * Indica si la Accion esta o no dentro del menu
		 * @return the column 'menu' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public Integer getMenu()
		throws SQLException {
			return rs.getInt("menu"+suffix );
		}
		/**
		 * Nombre de la Accion
		 * @return the column 'name' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public String getName()
		throws SQLException {
			return rs.getString("name"+suffix);
		}
		/**
		 * Aplicacion a la que pertenece la Accion
		 * @return the column 'application_id' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public Integer getApplication_id()
		throws SQLException {
			return rs.getInt("application_id"+suffix );
		}

		
		private Application fk_action_app; 
		
		/**
		 * @throws SQLException
		 */
		public Application getFk_action_app()
		throws SQLException {
			if ( this.fk_action_app == null )
				this.fk_action_app = new Application(rs, "1");
			return this.fk_action_app;
		}

		
		private PreparedStatement Action_deniedStmt;
		
		private void initAction_deniedStmt() 
		throws SQLException{
			Action_deniedStmt = ctsqlConnection.prepareStatement(
					"SELECT *"
					+ " FROM action_denied"
					+ " WHERE" 
					+ " action_id = ?  " 				); 
		}
		
		private void closeAction_deniedStmt() 
		throws SQLException{
			Action_deniedStmt.close();
		}


		public void visitAction_denied(CtsqlDBVisitor ctsqlDBVisitor) throws SQLException{
			ResultSet 			rs 	= null;
			boolean				resume 	= true;
	
			try {
				
				this.Action_deniedStmt.setInt(1, this.getId() ); 
				rs = this.Action_deniedStmt.executeQuery();
				Action_denied action_denied = new Action_denied(rs); 
				while ( resume && rs.next() ) {
					resume = ctsqlDBVisitor.visitAction_denied(action_denied, this);
				}
			}
			finally {
				if ( rs != null )
					rs.close();
			}
		}

		
	}
	
	
