	/**
	 * Nivel
	 * 
	 */
	public class Nivel {
		
		private ResultSet rs;
		
		private String suffix;
		
		private Nivel (ResultSet rs) 
		throws SQLException {
			this(rs, "");
		}
		
		private Nivel (ResultSet rs, String suffix) 
		throws SQLException {
			this.rs =rs;
			this.suffix = suffix;
			initPercnivStmt();
		}
		
		@Override
		protected void finalize() throws Throwable {
			closePercnivStmt();
			super.finalize();
		}
		

		/**
		 * Codigo de Convenio
		 * @return the column 'codcon' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public String getCodcon()
		throws SQLException {
			return rs.getString("codcon"+suffix);
		}
		/**
		 * Codigo de Nivel Retributivo
		 * @return the column 'cdg' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public String getCdg()
		throws SQLException {
			return rs.getString("cdg"+suffix);
		}

		
		private Convenio rel_niv_con; 
		
		/**
		 * @throws SQLException
		 */
		public Convenio getRel_niv_con()
		throws SQLException {
			if ( this.rel_niv_con == null )
				this.rel_niv_con = new Convenio(rs, "1");
			return this.rel_niv_con;
		}

		
		private PreparedStatement PercnivStmt;
		
		private void initPercnivStmt() 
		throws SQLException{
			PercnivStmt = ctsqlConnection.prepareStatement(
					"SELECT *"
					+ " FROM percniv"
					+ " WHERE" 
					+ " cdg = ?  "  + "AND" 					+ " nivel = ?  " 				); 
		}
		
		private void closePercnivStmt() 
		throws SQLException{
			PercnivStmt.close();
		}


		public void visitPercniv(CtsqlDBVisitor ctsqlDBVisitor) throws SQLException{
			ResultSet 			rs 	= null;
			boolean				resume 	= true;
	
			try {
				
				this.PercnivStmt.setString(1, this.getCodcon() ); 
				this.PercnivStmt.setString(2, this.getCdg() ); 
				rs = this.PercnivStmt.executeQuery();
				Percniv percniv = new Percniv(rs); 
				while ( resume && rs.next() ) {
					resume = ctsqlDBVisitor.visitPercniv(percniv, this);
				}
			}
			finally {
				if ( rs != null )
					rs.close();
			}
		}

		
	}
	
	
