	/**
	 * Tipempr
	 * 
	 */
	public class Tipempr {
		
		private ResultSet rs;
		
		private String suffix;
		
		private Tipempr (ResultSet rs) 
		throws SQLException {
			this(rs, "");
		}
		
		private Tipempr (ResultSet rs, String suffix) 
		throws SQLException {
			this.rs =rs;
			this.suffix = suffix;
			initClienteStmt();
			initEmprnifStmt();
		}
		
		@Override
		protected void finalize() throws Throwable {
			closeClienteStmt();
			closeEmprnifStmt();
			super.finalize();
		}
		

		/**
		 * Codigo de Tipo de Empresario
		 * @return the column 'cdg' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public String getCdg()
		throws SQLException {
			return rs.getString("cdg"+suffix);
		}
		/**
		 * Descripcion de Tipo de Empresario
		 * @return the column 'descripcion' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public String getDescripcion()
		throws SQLException {
			return rs.getString("descripcion"+suffix);
		}


		
		private PreparedStatement ClienteStmt;
		
		private void initClienteStmt() 
		throws SQLException{
			ClienteStmt = ctsqlConnection.prepareStatement(
					"SELECT *"
					+ " FROM cliente"
					+ " WHERE" 
					+ " tipemp = ?  " 				); 
		}
		
		private void closeClienteStmt() 
		throws SQLException{
			ClienteStmt.close();
		}


		public void visitCliente(CtsqlDBVisitor ctsqlDBVisitor) throws SQLException{
			ResultSet 			rs 	= null;
			boolean				resume 	= true;
	
			try {
				
				this.ClienteStmt.setString(1, this.getCdg() ); 
				rs = this.ClienteStmt.executeQuery();
				Cliente cliente = new Cliente(rs); 
				while ( resume && rs.next() ) {
					resume = ctsqlDBVisitor.visitCliente(cliente, this);
				}
			}
			finally {
				if ( rs != null )
					rs.close();
			}
		}
		
		private PreparedStatement EmprnifStmt;
		
		private void initEmprnifStmt() 
		throws SQLException{
			EmprnifStmt = ctsqlConnection.prepareStatement(
					"SELECT *"
					+ " FROM emprnif"
					+ " WHERE" 
					+ " tipempr = ?  " 				); 
		}
		
		private void closeEmprnifStmt() 
		throws SQLException{
			EmprnifStmt.close();
		}


		public void visitEmprnif(CtsqlDBVisitor ctsqlDBVisitor) throws SQLException{
			ResultSet 			rs 	= null;
			boolean				resume 	= true;
	
			try {
				
				this.EmprnifStmt.setString(1, this.getCdg() ); 
				rs = this.EmprnifStmt.executeQuery();
				Emprnif emprnif = new Emprnif(rs); 
				while ( resume && rs.next() ) {
					resume = ctsqlDBVisitor.visitEmprnif(emprnif, this);
				}
			}
			finally {
				if ( rs != null )
					rs.close();
			}
		}

		
	}
	
	
