	/**
	 * Application
	 * 
	 */
	public class Application {
		
		private ResultSet rs;
		
		private String suffix;
		
		private Application (ResultSet rs) 
		throws SQLException {
			this(rs, "");
		}
		
		private Application (ResultSet rs, String suffix) 
		throws SQLException {
			this.rs =rs;
			this.suffix = suffix;
			initSessionStmt();
			initActionStmt();
		}
		
		@Override
		protected void finalize() throws Throwable {
			closeSessionStmt();
			closeActionStmt();
			super.finalize();
		}
		

		/**
		 * Identificador unico
		 * @return the column 'id' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public Integer getId()
		throws SQLException {
			return rs.getInt("id"+suffix );
		}
		/**
		 * Nivel de auditoria
		 * @return the column 'audit_level' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public Integer getAudit_level()
		throws SQLException {
			return rs.getInt("audit_level"+suffix );
		}
		/**
		 * Nombre de la Aplicacion
		 * @return the column 'name' value; if the value is SQL NULL, the value returned is null
		 * @throws SQLException
		 */
		public String getName()
		throws SQLException {
			return rs.getString("name"+suffix);
		}


		
		private PreparedStatement SessionStmt;
		
		private void initSessionStmt() 
		throws SQLException{
			SessionStmt = ctsqlConnection.prepareStatement(
					"SELECT *"
					+ " FROM session"
					+ " WHERE" 
					+ " application_id = ?  " 				); 
		}
		
		private void closeSessionStmt() 
		throws SQLException{
			SessionStmt.close();
		}


		public void visitSession(CtsqlDBVisitor ctsqlDBVisitor) throws SQLException{
			ResultSet 			rs 	= null;
			boolean				resume 	= true;
	
			try {
				
				this.SessionStmt.setInt(1, this.getId() ); 
				rs = this.SessionStmt.executeQuery();
				Session session = new Session(rs); 
				while ( resume && rs.next() ) {
					resume = ctsqlDBVisitor.visitSession(session, this);
				}
			}
			finally {
				if ( rs != null )
					rs.close();
			}
		}
		
		private PreparedStatement ActionStmt;
		
		private void initActionStmt() 
		throws SQLException{
			ActionStmt = ctsqlConnection.prepareStatement(
					"SELECT *"
					+ " FROM action"
					+ " WHERE" 
					+ " application_id = ?  " 				); 
		}
		
		private void closeActionStmt() 
		throws SQLException{
			ActionStmt.close();
		}


		public void visitAction(CtsqlDBVisitor ctsqlDBVisitor) throws SQLException{
			ResultSet 			rs 	= null;
			boolean				resume 	= true;
	
			try {
				
				this.ActionStmt.setInt(1, this.getId() ); 
				rs = this.ActionStmt.executeQuery();
				Action action = new Action(rs); 
				while ( resume && rs.next() ) {
					resume = ctsqlDBVisitor.visitAction(action, this);
				}
			}
			finally {
				if ( rs != null )
					rs.close();
			}
		}

		
	}
	
	
