		private PreparedStatement LcomunicaStmt;
		
		private void initLcomunicaStmt() 
		throws SQLException{
			LcomunicaStmt = ctsqlConnection.prepareStatement(
					"SELECT *"
					+ " FROM lcomunica"
					+ " WHERE" 
					+ " cdg = ?  "  + "AND" 					+ " numero = ?  " 				); 
		}
		
		private void closeLcomunicaStmt() 
		throws SQLException{
			LcomunicaStmt.close();
		}


		public void visitLcomunica(CtsqlDBVisitor ctsqlDBVisitor) throws SQLException{
			ResultSet 			rs 	= null;
			boolean				resume 	= true;
	
			try {
				
				this.LcomunicaStmt.setInt(1, this.getCdg() ); 
				this.LcomunicaStmt.setInt(2, this.getNumero() ); 
				rs = this.LcomunicaStmt.executeQuery();
				Lcomunica lcomunica = new Lcomunica(rs); 
				while ( resume && rs.next() ) {
					resume = ctsqlDBVisitor.visitLcomunica(lcomunica, this);
				}
			}
			finally {
				if ( rs != null )
					rs.close();
			}
		}
		
		private PreparedStatement LbonificaStmt;
		
