		private PreparedStatement EmprctraStmt;
		
		private void initEmprctraStmt() 
		throws SQLException{
			EmprctraStmt = ctsqlConnection.prepareStatement(
					"SELECT *"
					+ " FROM emprctra"
					+ " WHERE" 
					+ " codact = ?  " 				); 
		}
		
		private void closeEmprctraStmt() 
		throws SQLException{
			EmprctraStmt.close();
		}


		public void visitEmprctra(CtsqlDBVisitor ctsqlDBVisitor) throws SQLException{
			ResultSet 			rs 	= null;
			boolean				resume 	= true;
	
			try {
				
				this.EmprctraStmt.setInt(1, this.getCdg() ); 
				rs = this.EmprctraStmt.executeQuery();
				Emprctra emprctra = new Emprctra(rs); 
				while ( resume && rs.next() ) {
					resume = ctsqlDBVisitor.visitEmprctra(emprctra, this);
				}
			}
			finally {
				if ( rs != null )
					rs.close();
			}
		}
		
